import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem126 preserva oferta e afiliado',()=>{for(const [id,titulo,expected,link] of [["Q8XN2tGmsU12afIbz1Am","Fritadeira Elétrica Sem Óleo Air Fryer Mondial 1500w","Air fryer Mondial — 4 L e 1.500 W anunciados","https://produto.mercadolivre.com.br/MLB-1307284888-fritadeira-eletrica-sem-oleo-air-fryer-mondial-1500w-_JM"],["Q9UWVUsXl8sIvWyM1hKt","Lixeira Metal Aramado Telada Cesto De Lixo Escritório 12l Cor Preto","Lixeira aramada preta — 12 L anunciados","https://www.mercadolivre.com.br/up/MLBU3407282880?pdp_filters=item_id%3AMLB5666993474"],["qeH6DeH4aWWppBpaRPYc","Creatina 100% Monohidratada Micronizada Vegana True Source","Creatina monohidratada True Source — 300 g anunciados","https://www.mercadolivre.com.br/up/MLBU3368370235?pdp_filters=item_id%3AMLB5604818552"]]){const p={id,titulo,link,linkAfiliado:'https://meli.la/preservar',preco:'preservar'},x=correctProductData(p);assert.ok(x.comentario.length>=180);assert.equal(x.titulo,expected);for(const k of ['id','link','linkAfiliado','preco'])assert.equal(x[k],p[k]);assert.deepEqual(correctProductData(x),x);}});
